export const FALLBACK_FACT: PackageTheftFact = {
  id: 0,
  date: "00-00",
  factText: "Package theft is a multibillion-dollar problem affecting tens of millions of deliveries each year. Protect your doorstep.",
  sourceName: "USPS OIG",
  sourceUrl: "https://www.uspsoig.gov/reports/white-papers/package-theft-united-states",
};

export function getTodayFact(dateOverride?: string): PackageTheftFact {
  try {
    const now = dateOverride ? new Date(dateOverride) : new Date();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const dateKey = `${month}-${day}`;

    const fact = dailyPackageTheftFacts.find(f => f.date === dateKey);

    if (fact) {
      log('[DailyFact] Loaded fact for', dateKey, ':', fact.factText.substring(0, 50) + '...');
      return fact;
    }

    log('[DailyFact] No fact found for', dateKey, ', using fallback');
    return FALLBACK_FACT;
  } catch (error) {
    log('[DailyFact] Error loading fact:', error);
    return FALLBACK_FACT;
  }
}

export default dailyPackageTheftFacts;
